WHERE wordbook_id = #{wordbookId}
  AND normalized_term = #{normalizedTerm}
LIMIT 1

SELECT *
FROM learning_wordbook_entry
WHERE wordbook_id = #{wordbookId}


        AND normalized_term IN
        #{term}


        AND 1 = 0

SELECT e.id, e.wordbook_id AS wordbookId, e.vocabulary_id AS vocabularyId, e.term, e.normalized_term AS normalizedTerm, COALESCE( JSON_UNQUOTE(JSON_EXTRACT(e.snapshot_parsed_json, '$.phonetic.uk')), JSON_UNQUOTE(JSON_EXTRACT(e.snapshot_parsed_json, '$.phonetic.us')), JSON_UNQUOTE(JSON_EXTRACT(e.snapshot_parsed_json, '$.phonetic_uk')), JSON_UNQUOTE(JSON_EXTRACT(e.snapshot_parsed_json, '$.phonetic_us')) ) AS phonetic, COALESCE( JSON_UNQUOTE(JSON_EXTRACT(e.snapshot_parsed_json, '$.definitions[0].meaning')), JSON_UNQUOTE(JSON_EXTRACT(e.snapshot_parsed_json, '$.definitions[0].cn')), JSON_UNQUOTE(JSON_EXTRACT(e.snapshot_parsed_json, '$.definitions[0].definition')), JSON_UNQUOTE(JSON_EXTRACT(e.snapshot_parsed_json, '$.meaning')) ) AS meaningText, e.status, e.review_stage AS reviewStage, e.mastery_score AS masteryScore, e.last_review_time AS lastReviewTime, e.next_review_time AS nextReviewTime, e.review_count AS reviewCount, e.correct_count AS correctCount, e.wrong_count AS wrongCount, e.card_status AS cardStatus, e.create_time AS createTime FROM learning_wordbook_entry e WHERE e.user_id = #{userId} AND e.wordbook_id = #{wordbookId} AND e.deleted = 0
AND e.status = #{status}
AND (e.term LIKE CONCAT(#{keyword}, '%') OR e.normalized_term LIKE CONCAT(LOWER(#{keyword}), '%'))
AND e.next_review_time <= #{now}
ORDER BY e.next_review_time ASC, e.create_time DESC

